"use strict";
(function () {
  var W = 32, H = 32, FPS = 30, NFRAMES = 6572;
  var DATA = "";
  var frameBytes = W * H / 8;

  function renderFrame(idx, raw, out) {
    var off = (idx % NFRAMES) * frameBytes;
    for (var y = 0; y < H; y++) {
      var line = out[y];
      var base = y * W;
      for (var x = 0; x < W; x++) {
        var p = base + x;
        var on = (raw[off + (p >> 3)] & (1 << (7 - (p & 7)))) !== 0;
        line[x * 2] = on ? "\u2588" : " ";
        line[x * 2 + 1] = on ? "\u2588" : " ";
      }
    }
  }

  function init(container) {
    var pre = document.createElement("pre");
    pre.className = "badapple-frame";
    container.appendChild(pre);

    var out = [];
    var i, y;
    for (y = 0; y < H; y++) out.push(new Array(W * 2));
    pre.textContent = "";

    var bytes;
    try { bytes = atob(DATA); } catch (e) { return; }
    var rawBytes = new Uint8Array(bytes.length);
    for (i = 0; i < bytes.length; i++) rawBytes[i] = bytes.charCodeAt(i);

    try {
      var ds = new DecompressionStream("deflate");
      var stream = new Blob([rawBytes]).stream().pipeThrough(ds);
      new Response(stream).arrayBuffer().then(function (buf) {
        var raw = new Uint8Array(buf);
        var idx = 0, last = performance.now(), interval = 1000 / FPS;
        pre.classList.add("ready");
        (function tick(now) {
          var el = now - last;
          if (el >= interval) {
            renderFrame(idx, raw, out);
            var s = "";
            for (y = 0; y < H; y++) s += out[y].join("") + "\n";
            pre.textContent = s;
            idx = (idx + 1) % NFRAMES;
            last = now - (el % interval);
          }
          requestAnimationFrame(tick);
        })(performance.now());
      });
    } catch (e) { /* DecompressionStream unsupported */ }
  }

  function boot() {
    var el = document.getElementById("badapple-stage");
    if (el) init(el);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();
